  font-weight: 400;
}

@page {
  size: 210mm 297mm;
  margin: 0;
}

html,
body {
  margin: 0 !important;
  padding: 0 !important;
}

.print-format {
  width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  margin-top: 0 !important;
  margin-right: 0 !important;
  margin-bottom: 0 !important;
  margin-left: 0 !important;
  padding: 0 !important;
}

.cd-invoice,
.cd-invoice * {
  box-sizing: border-box;
}

.cd-invoice {
  position: relative;
  width: 210mm;
  height: 297mm;
  margin: 0;
  overflow: hidden;
  color: #292929;
