  background: #fff;
  font-family: "TH Sarabun Document", "TH SarabunPSK", sans-serif;
  font-size: 4.516mm;
  font-weight: 400;
  line-height: 1;
  page-break-after: always;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.cd-invoice.last-page {
  page-break-after: auto;
}

